function LongestConsecutive(nums: int[]) -> int {
  let present: map<string, bool> = {};
  let i = 0;
  while (i < nums.length()) {
    present.set(nums[i].to_string(), true);
    i += 1;
  }
  let best = 0;
  let j = 0;
  while (j < nums.length()) {
    let num = nums[j];
    if (present.has((num - 1).to_string()) == false) {
      let len = 1;
      let cur = num;
      while (present.has((cur + 1).to_string())) {
        cur += 1;
        len += 1;
      }
      if (len > best) {
        best = len;
      }
    }
    j += 1;
  }
  return best;
}
